static uint8_t param_is_structural(param_id_t id){switch(id){case PARAM_CFG_TRACK:case PARAM_CFG_TRACK_TYPE:case PARAM_CFG_MIDI_CH:case PARAM_CFG_MIDI_SRC:case PARAM_CFG_START:case PARAM_CFG_TEMPO:case PARAM_CFG_SYNC:case PARAM_CFG_REC_LEN:case PARAM_SEQ_LENGTH:case PARAM_SEQ_DIV:case PARAM_SEQ_QUANT:case PARAM_SEQ_SWING:case PARAM_MOD_MATRIX_SLOT:case PARAM_MOD_MATRIX_SOURCE:case PARAM_MOD_MATRIX_DEST:case PARAM_MOD_MATRIX_DEPTH:case PARAM_MOD_MULTI_1_A:case PARAM_MOD_MULTI_1_B:case PARAM_MOD_MULTI_2_A:case PARAM_MOD_MULTI_2_B:case PARAM_MOD_SLEW_1_SOURCE:case PARAM_MOD_SLEW_1_AMOUNT:case PARAM_MOD_SLEW_2_SOURCE:case PARAM_MOD_SLEW_2_AMOUNT:case PARAM_LFO1_RATE:case PARAM_LFO1_SHAPE:case PARAM_LFO1_TRIG:case PARAM_LFO1_PHASE:case PARAM_LFO2_RATE:case PARAM_LFO2_SHAPE:case PARAM_LFO2_TRIG:case PARAM_LFO2_PHASE:case PARAM_LFO3_RATE:case PARAM_LFO3_SHAPE:case PARAM_LFO3_TRIG:case PARAM_LFO3_PHASE:case PARAM_ENV3_ATTACK:case PARAM_ENV3_DECAY:case PARAM_ENV3_SUSTAIN:case PARAM_ENV3_RELEASE:case PARAM_ENV_RETRIG_MOD:case PARAM_SAMPLER_SAMPLE:case PARAM_EXTERNAL_INPUT:return 1U;default:return (uint8_t)(((id>=PARAM_SEQ_PLAY_V1_NOTE&&id<=PARAM_SEQ_PLAY_V8_MICTIM)||(id>=PARAM_MIDI_FX_S1_PARAM1&&id<=PARAM_MIDI_FX_S3_MODEL))?1U:0U);}}
static persist_param_scope_t param_scope(param_id_t id){switch(id){case PARAM_MODFX_MODEL:case PARAM_MODFX_RATE:case PARAM_MODFX_DEPTH:case PARAM_MODFX_FEEDBACK:case PARAM_MODFX_OFFSET:case PARAM_MIX_REVERB_WET:case PARAM_MIX_REVERB_ROOM_SIZE:case PARAM_MIX_REVERB_DAMPING:case PARAM_MIX_REVERB_WIDTH:case PARAM_MIX_REVERB_HPF:case PARAM_MIX_DELAY_TYPE:case PARAM_MIX_DELAY_TIME:case PARAM_MIX_DELAY_PINGPONG:case PARAM_MIX_DELAY_MODE:case PARAM_MIX_DELAY_TIME_R:case PARAM_MIX_DELAY_WIDTH:case PARAM_MIX_DELAY_FEEDBACK:case PARAM_MIX_DELAY_SPECTRAL_POSITION:case PARAM_MIX_DELAY_SPECTRAL_WIDTH:case PARAM_MIX_DELAY_FBW:case PARAM_MIX_REVERB_DELAYS:case PARAM_MIX_DELAY_MOD:case PARAM_MIX_DELAY_MOD_RATE:case PARAM_MIX_DELAY_REV:case PARAM_MIX_DELAY_VOL:case PARAM_BUS_COMP_THRESHOLD_DB:case PARAM_BUS_COMP_RATIO:case PARAM_BUS_COMP_ATTACK_INDEX:case PARAM_BUS_COMP_RELEASE_INDEX:case PARAM_BUS_COMP_MAKEUP_DB:case PARAM_BUS_COMP_AUTO_MAKEUP:case PARAM_BUS_COMP_DRYWET:case PARAM_BUS_COMP_HPF_HZ:case PARAM_COMP_MODEL:case PARAM_COMP_DETECT:case PARAM_COMP_KNEE_DB:case PARAM_COMP_DELUGE_SAT:case PARAM_MASTER_GAIN:case PARAM_POST_GAIN:case PARAM_OUTPUT_COMP:return PERSIST_PARAM_SCOPE_GLOBAL;default:return PERSIST_PARAM_SCOPE_ENTITY;}}
