uint8_t persist_key_param_descriptor(param_id_t id,persist_param_descriptor_t *out){if(out==NULL||id>=PARAM_COUNT||param_id_is_reserved(id))return 0U;out->key=g_param_keys[id];out->kind=param_kind(id);out->scope=((id>=PARAM_MODFX_BANK_DELUGE_MONO_AB)&&(id<=PARAM_MODFX_BANK_JUNOLOGUE_CD))?PERSIST_PARAM_SCOPE_GLOBAL:param_scope(id);out->persistent=(uint8_t)((param_is_structural(id)==0U)&&!((id>=PARAM_FM_UI_FIRST)&&(id<=PARAM_FM_UI_LAST)));out->plockable=seq_param_iface_is_param_plockable(id);return 1U;}
uint8_t persist_key_param_to_disk(param_id_t id,persist_control_parameter_key_t *out){persist_param_descriptor_t d;if(out==NULL||persist_key_param_descriptor(id,&d)==0U)return 0U;*out=d.key;return 1U;}
uint8_t persist_key_param_from_disk(persist_control_parameter_key_t key,param_id_t *out){if(out==NULL||key==0U)return 0U;for(param_id_t id=0U;id<PARAM_COUNT;++id)if(!param_id_is_reserved(id)&&g_param_keys[id]==key){*out=id;return 1U;}return 0U;}
