static const uint32_t lfo_triggers[]={PERSIST_LFO_TRIGGER_FREE,PERSIST_LFO_TRIGGER_TRIG,PERSIST_LFO_TRIGGER_HOLD,PERSIST_LFO_TRIGGER_ONE,PERSIST_LFO_TRIGGER_POLY_TRIG,PERSIST_LFO_TRIGGER_POLY_HOLD,PERSIST_LFO_TRIGGER_POLY_ONE};
uint8_t persist_key_lfo_trigger_to_disk(mod_lfo_trig_mode_t v,uint32_t*out){if(out==NULL||(uint8_t)v>=MOD_LFO_TRIG_COUNT)return 0U;*out=lfo_triggers[v];return 1U;}uint8_t persist_key_lfo_trigger_from_disk(uint32_t k,mod_lfo_trig_mode_t*out){if(out==NULL)return 0U;for(uint8_t i=0U;i<MOD_LFO_TRIG_COUNT;++i)if(lfo_triggers[i]==k){*out=(mod_lfo_trig_mode_t)i;return 1U;}return 0U;}
static const uint32_t mod_sources[]={PERSIST_MOD_SOURCE_NONE,PERSIST_MOD_SOURCE_LFO1,PERSIST_MOD_SOURCE_LFO2,PERSIST_MOD_SOURCE_LFO3,PERSIST_MOD_SOURCE_ENV_FLT,PERSIST_MOD_SOURCE_ENV_VCA,PERSIST_MOD_SOURCE_ENV_MOD,PERSIST_MOD_SOURCE_MULTI1,PERSIST_MOD_SOURCE_MULTI2,PERSIST_MOD_SOURCE_SLEW1,PERSIST_MOD_SOURCE_SLEW2};
uint8_t persist_key_mod_source_to_disk(uint8_t v,uint32_t*out){if(out==NULL||v>=11U)return 0U;*out=mod_sources[v];return 1U;}uint8_t persist_key_mod_source_from_disk(uint32_t k,uint8_t*out){if(out==NULL)return 0U;for(uint8_t i=0U;i<11U;++i)if(mod_sources[i]==k){*out=i;return 1U;}return 0U;}
static const uint32_t rec_start[]={PERSIST_RECORD_START_DEFAULT,PERSIST_RECORD_START_TRIGGER,PERSIST_RECORD_START_ROLL_QUARTER,PERSIST_RECORD_START_ROLL_HALF,PERSIST_RECORD_START_ROLL_BAR};static const uint32_t rec_len[]={PERSIST_RECORD_LENGTH_OVERDUB,PERSIST_RECORD_LENGTH_PATTERN};
static uint8_t array_to(uint8_t v,const uint32_t*a,uint8_t n,uint32_t*out){if(out==NULL||v>=n)return 0U;*out=a[v];return 1U;}static uint8_t array_from(uint32_t k,const uint32_t*a,uint8_t n,uint8_t*out){if(out==NULL)return 0U;for(uint8_t i=0U;i<n;++i)if(a[i]==k){*out=i;return 1U;}return 0U;}
uint8_t persist_key_record_start_to_disk(uint8_t v,uint32_t*out){return array_to(v,rec_start,5U,out);}uint8_t persist_key_record_start_from_disk(uint32_t k,uint8_t*out){return array_from(k,rec_start,5U,out);}uint8_t persist_key_record_length_to_disk(uint8_t v,uint32_t*out){return array_to(v,rec_len,2U,out);}uint8_t persist_key_record_length_from_disk(uint32_t k,uint8_t*out){return array_from(k,rec_len,2U,out);}
uint8_t persist_key_input_to_disk(uint8_t v,uint32_t*out){if(out==NULL||v>1U)return 0U;*out=(v==0U)?PERSIST_INPUT_NONE:PERSIST_INPUT_PHYSICAL_1;return 1U;}uint8_t persist_key_input_from_disk(uint32_t k,uint8_t*out){if(out==NULL)return 0U;if(k==PERSIST_INPUT_NONE){*out=0U;return 1U;}if(k==PERSIST_INPUT_PHYSICAL_1){*out=1U;return 1U;}return 0U;}
uint8_t persist_key_mod_destination_to_disk(uint8_t e,param_id_t p,persist_control_entity_id_t*oe,persist_control_parameter_key_t*op){if(oe==NULL||op==NULL||e>=PERSIST_CONTROL_ENTITY_COUNT||persist_key_param_to_disk(p,op)==0U)return 0U;*oe=e;return 1U;}
uint8_t persist_key_mod_destination_from_disk(persist_control_entity_id_t e,persist_control_parameter_key_t p,uint8_t active,uint8_t*oe,param_id_t*op){entity_topology_descriptor_t d;if(oe==NULL||op==NULL||entity_topology_resolve(active,e,&d)==0U||d.active==0U||persist_key_param_from_disk(p,op)==0U)return 0U;*oe=e;return 1U;}
